int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    ll *A = (ll *)malloc((N + 1) * sizeof(ll));
    ll *pos = (ll *)malloc((N + 1) * sizeof(ll));
    for (int i = 1; i <= N - 1; i++) scanf("%lld", &A[i]);

    pos[1] = 0;
    for (int i = 2; i <= N; i++) pos[i] = pos[i - 1] + A[i - 1];

    ll *dp = (ll *)malloc((N + 1) * sizeof(ll));
    ll *ndp = (ll *)malloc((N + 1) * sizeof(ll));

    for (int i = 1; i <= N; i++) dp[i] = 0;

    for (int t = 1; t <= M; t++) {
        ll *B = (ll *)malloc((N + 1) * sizeof(ll));
        for (int i = 1; i <= N; i++) scanf("%lld", &B[i]);

        ll bestLeft = -(1LL << 60);
        for (int i = 1; i <= N; i++) {
            ll cand = dp[i] + pos[i];
            if (cand > bestLeft) bestLeft = cand;
            ndp[i] = B[i] - pos[i] + bestLeft;
        }

        ll bestRight = -(1LL << 60);
        for (int i = N; i >= 1; i--) {
            ll cand = dp[i] - pos[i];
            if (cand > bestRight) bestRight = cand;
            ll val = B[i] + pos[i] + bestRight;
            if (val > ndp[i]) ndp[i] = val;
        }

        for (int i = 1; i <= N; i++) dp[i] = maxll(dp[i], ndp[i]);

        free(B);
    }

    ll ans = 0;
    for (int i = 1; i <= N; i++) ans = maxll(ans, dp[i]);

    printf("%lld\n", ans);

    free(A);
    free(pos);
    free(dp);
    free(ndp);
    return 0;
}

