using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<ll> A(N - 1);
    for (int i = 0; i < N - 1; i++) cin >> A[i];

    vector<vector<ll>> B(N, vector<ll>(M));
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) cin >> B[i][j];
    }

    // prefix distances: pos[i] = distance from restaurant 1 to restaurant i+1
    vector<ll> pos(N, 0);
    for (int i = 1; i < N; i++) pos[i] = pos[i - 1] + A[i - 1];

    int FULL = 1 << M;

    // gain[i][mask] = total deliciousness obtainable at restaurant i using tickets in mask
    vector<vector<ll>> gain(N, vector<ll>(FULL, 0));
    for (int i = 0; i < N; i++) {
        for (int mask = 1; mask < FULL; mask++) {
            int b = __builtin_ctz(mask);
            gain[i][mask] = gain[i][mask ^ (1 << b)] + B[i][b];
        }
    }

    const ll NEG = -(1LL << 60);

    // dpL[i][mask]:
    // maximum happiness when ending at restaurant i,
    // using exactly tickets in mask, and only moving east (start somewhere to the west or at i)
    vector<vector<ll>> dpL(N, vector<ll>(FULL, NEG));

    for (int mask = 0; mask < FULL; mask++) dpL[0][mask] = gain[0][mask];
    for (int i = 1; i < N; i++) {
        for (int mask = 0; mask < FULL; mask++) {
            dpL[i][mask] = max(gain[i][mask], dpL[i - 1][mask] - A[i - 1] + gain[i][mask]);
        }
    }

    // dpR[i][mask]:
    // maximum happiness when ending at restaurant i,
    // using exactly tickets in mask, and only moving west (start somewhere to the east or at i)
    vector<vector<ll>> dpR(N, vector<ll>(FULL, NEG));

    for (int mask = 0; mask < FULL; mask++) dpR[N - 1][mask] = gain[N - 1][mask];
    for (int i = N - 2; i >= 0; i--) {
        for (int mask = 0; mask < FULL; mask++) {
            dpR[i][mask] = max(gain[i][mask], dpR[i + 1][mask] - A[i] + gain[i][mask]);
        }
    }

    ll ans = 0;

    // Path can be represented as:
    // choose turning point i, collect some tickets on a monotone path from left to i,
    // and the remaining tickets on a monotone path from right to i.
    // Since restaurant i can be visited by both parts, subtract gain[i][FULL-1] once.
    for (int i = 0; i < N; i++) {
        for (int mask = 0; mask < FULL; mask++) {
            ll cand = dpL[i][mask] + dpR[i][(FULL - 1) ^ mask] - gain[i][FULL - 1];
            ans = max(ans, cand);
        }
    }

    cout << ans << '\n';
    return 0;
}

