        Arrays.sort(B);
        long[] prefixB = new long[M + 1];
        for (int i = 0; i < M; i++) {
            prefixB[i + 1] = prefixB[i] + B[M - 1 - i];
        }

        // Prefix sum of distances
        long[] prefixDist = new long[N + 1];
        for (int i = 1; i < N; i++) {
            prefixDist[i] = prefixDist[i - 1] + A[i - 1];
        }
        // We don't really need prefixDist[N] but for completeness
        prefixDist[N] = prefixDist[N - 1] + A[N - 1];

        long maxHappiness = 0;

        // Try every start
