            // Try every end >= start
            for (int end = start; end < N; end++) {
                int count = end - start + 1;
                if (count > M) break; // not enough tickets
                long travelCost = prefixDist[end] - prefixDist[start];
                long deliciousSum = prefixB[count]; // sum of top count deliciousness
                long happiness = deliciousSum - travelCost;
                if (happiness > maxHappiness) {
                    maxHappiness = happiness;
                }
            }
        }

        System.out.println(maxHappiness);
