        // happiness = sum_t max_{i in [l,r]} B[i][t] - (pos[r]-pos[l]).
        // For each mask, define C_mask[i] = sum of B[i][t] for t in mask.
        // By subset DP over maxima:
        // f[mask] = max over i C_mask[i]
        // Answer = max over partition (S, T disjoint): max_i C_S[i] + max_j C_T[j] - |pos[i]-pos[j]|
        // Let g[mask][i] = max_{j} C_mask[j] - |pos[i]-pos[j]|
        // Then answer = max_mask max_i C_mask[i] + g[all^mask][i]

        long[] bestAtMask = new long[S];
        for (int mask = 0; mask < S; mask++) {
            long mx = 0;
            for (int i = 1; i <= N; i++) {
                if (val[mask][i] > mx) mx = val[mask][i];
            }
            bestAtMask[mask] = mx;
        }

        long[][] g = new long[S][N + 1];
        for (int mask = 0; mask < S; mask++) {
            long left = Long.MIN_VALUE / 4;
            for (int i = 1; i <= N; i++) {
                left = Math.max(left, val[mask][i] + pos[i]);
                g[mask][i] = left - pos[i];
            }
            long right = Long.MIN_VALUE / 4;
            for (int i = N; i >= 1; i--) {
                right = Math.max(right, val[mask][i] - pos[i]);
                g[mask][i] = Math.max(g[mask][i], right + pos[i]);
            }
        }

        int all = S - 1;
        answer = 0;
        for (int mask = 0; mask < S; mask++) {
            int other = all ^ mask;
            for (int i = 1; i <= N; i++) {
                answer = Math.max(answer, val[mask][i] + g[other][i]);
            }
        }

        System.out.println(answer);
    }
}
